{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/research_contract.py",
      "detail": "Identity validation requires a field value in the fact statement, but not in its supporting quotation. A drivetrain fact stating AWD can therefore be bound to an unrelated quotation from a source whose declared scope matches the intake. Matching scope labels alone do not establish that the source supports the field.",
      "required_fix": "Bind each identity value to directly supporting source text and its exact vehicle context; add active-article tests for unrelated quotations and mismatched identity values."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/research_contract.py",
      "detail": "The standard gate relies on a limited expression and skips classification checks for facts labeled editorial_method. A regulation cited without a recognized term, or mislabeled as an editorial method, can bypass current-version and primary-source requirements.",
      "required_fix": "Classify regulatory and standards claims independently of the supplied kind flag, fail closed when classification is uncertain, and test alternate citation formats and mislabeled mandatory claims."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py; cloud_pilot/multilingual/research_contract.py",
      "detail": "CROSS_CHECKED requires two parent organizations but does not restrict the sources to tiers permitted for the fact. For the Q05 intake, Autohome and YooJia are declared T3; the gate can therefore accept their agreement as support for a core vehicle specification even though the repository limits T3 to background, process and case-study use.",
      "required_fix": "Enforce fact-specific source-tier eligibility. Reclassify structured sources only after validating their actual publisher and content, and test that two T3 sources cannot establish a key vehicle specification."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/research_contract.py",
      "detail": "The engine never sets a durable WRITING_LOCK while writing. It requires writing_locked=false and compares only its cached research checkpoint, so concurrent Research changes outside that immutable checkpoint are not signaled through UPDATE_REQUIRED or RESEARCH_CHANGED_AFTER_WRITING_STARTED.",
      "required_fix": "Implement durable per-article lock and update signaling, re-read the current versioned Research handoff before completion, and test a Research change during writing."
    },
    {
      "severity": "high",
      "file": ".github/workflows/cloud-pilot-trusted.yml",
      "detail": "The account-check job exposes the project key to code selected by AUTOBRIDGE_APPROVED_CODE_SHA without the protected permit and workflow-lease preauthorization used by execute. The application-level SHA check runs only after that selected code has received the key; the protected environment review does not itself bind the code to a reviewed account-check implementation.",
      "required_fix": "Run account checks from an independently pinned implementation, or validate a protected, code-bound account-check permit before exposing the project key."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/source_cache.py",
      "detail": "When a target evidence checkpoint already exists, restore validates its declarations and internal hashes but does not compare its raw hashes, retrieval times or target hash with the approved origin transfer. It can then produce a transfer receipt associating cached evidence with an origin it did not verify against that cache.",
      "required_fix": "Bind every required transfer to the approved origin and expected target, and verify raw hashes, retrieval times, source declarations and target digest even when the target checkpoint already exists."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
